import pathlib,json,hashlib
OUT=pathlib.Path(__file__).resolve().parent
ROOT=OUT.parents[2]
SRC=ROOT/'00.Proiect/09. Vertraege/2026.10.13 Baza comuna negociere BERGER PECH/2026.10.13 R06 propuneri negociere'
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
docs={pr:load(SRC/f'2026.10.13 Werkvertrag {pr} R06 Entwurf.json') for pr in ['BERGER','PECH']}
expected={'BERGER':'b2a5254c4806e4067eadd6d17613b815bcb5d7d85020f672cc32b1964a420d56','PECH':'edf8d2831118f5137cb5e616df0a96172ff4aa3781617ded5291668bda84e101'}
for pr in docs:assert sha(SRC/f'2026.10.13 Werkvertrag {pr} R06 Entwurf.json')==expected[pr]
rows=[]
def get(pr,path):
 x=docs[pr]
 for k in path.strip('/').split('/'):x=x[int(k)] if isinstance(x,list) else x[k]
 return x
def propose(pr,path,new,reason,keep='Nur Darstellung; operative Rechte, Pflichten und Zahlen bleiben erhalten.'):
 old=get(pr,path)
 assert isinstance(old,str) and isinstance(new,str) and old!=new,(pr,path)
 rows.append({'id':f'E{len(rows)+1:03}','provider':pr,'pointer':path,'original_R06':old,'replacement_DE':new,'reason_RO':reason,'preserved_DE':keep,'status':'PROPUNERE EDITORIALĂ; NEAPLICATĂ CONTRACTELOR'})
def both(path,new,reason,keep='Nur Darstellung; operative Rechte, Pflichten und Zahlen bleiben erhalten.'):
 for pr in docs:propose(pr,path,new,reason,keep)
def change(pr,path,pairs,reason,keep='Nur Darstellung; operative Rechte, Pflichten und Zahlen bleiben erhalten.'):
 new=get(pr,path)
 for old,replacement in pairs:
  assert old in new,(pr,path,old)
  new=new.replace(old,replacement)
 propose(pr,path,new,reason,keep)
def bothchange(path,pairs,reason,keep='Nur Darstellung; operative Rechte, Pflichten und Zahlen bleiben erhalten.'):
 for pr in docs:change(pr,path,pairs,reason,keep)

both('/title','WERKVERTRAG - VERTRAGSVORSCHLAG A&C WOHNART','Titlul nu trebuie să anunțe negocierea sau comparația.')
both('/version','R07 Vertragsvorschlag','Metadată de versiune; elimină Verhandlungsentwurf. Nu susține acceptare.')
both('/preamble/1','Vertragsvorschlag der A&C Wohnart Immobilien GmbH. Der Vertrag einschließlich sämtlicher Anlagen wird erst durch vollständige beiderseitige Unterzeichnung verbindlich. Diese Vorlage begründet für sich weder eine Auftragserteilung noch eine Annahme.','Elimină Verhandlung, istoric ofertă și termen istoric; păstrează caracterul de propunere și lipsa unei comenzi/acceptări actuale.')
both('/preamble/2','Der Leistungsumfang umfasst achtzehn Kalendermonate Bauphase ab tatsächlichem B0, zwölf enthaltene physische B0-Ortstermine und die zusätzlich enthaltene anfängliche T0-Begehung. Bis zu sechs weitere physische Ortstermine können einzeln wirksam beauftragt werden. Honorarpositionen und Preise sind in Anlage 4 festgelegt. Aktuelle Vertretung, Team, Nachweise und tatsächliche Termine sind vor Unterzeichnung zu bestätigen.','Elimină «für beide Anbieter», «identische» și «anbieterabhängig»; păstrează 18 luni, 12+6 și T0 separat.')
bothchange('/sections/0/paragraphs/0',[(' Historische Unterlagen benennen die Geschäftsführer Cosmin-Adrian Covaciu und Anastasia-Elena-Ekaterina Covaciu; sie ersetzen keinen aktuellen Vertretungsnachweis.',' Die aktuelle Vertretungsberechtigung der tatsächlich unterzeichnenden Person ist zu belegen.')],'Proveniența documentelor firmei rămâne internă; verificarea actuală se păstrează. Numele societății, FN, UID și adresa nu se schimbă.')
change('BERGER','/sections/0/paragraphs/1',[('Diese Angaben beruhen auf dem Originalangebot und veröffentlichten Firmendaten; UID und Vertretung sind vor Unterzeichnung aktuell zu bestätigen.','UID und Vertretung sind vor Unterzeichnung aktuell zu bestätigen.'),(' ein historisch beziehungsweise öffentlich benannter Geschäftsführer ersetzt keinen aktuellen Vertretungsnachweis.',' die aktuelle Vertretungsberechtigung ist zu belegen.')],'Elimină proveniența istorică comercială; păstrează identitățile și proba reprezentării actuale.')
change('PECH','/sections/0/paragraphs/1',[('Angaben beruhen auf dem Originalangebot und veröffentlichten Firmendaten; aktuelle Firmenbuchdaten und tatsächliche Vertretung sind vor Unterzeichnung zu bestätigen.','Aktuelle Firmenbuchdaten und tatsächliche Vertretung sind vor Unterzeichnung zu bestätigen.')],'Elimină proveniența ofertei din clauza de identitate; păstrează separarea contactului Ployer de semnatar.')
bothchange('/sections/1/paragraphs/2',[('unverändertes Originalangebot in Anlage 5','Angebot des AN in Anlage 5'),('Das Originalangebot gilt ergänzend','Das Angebot des AN gilt ergänzend')],'Neutralizează denumirea ofertei fără a modifica ordinea documentelor sau încorporarea complementară.','Nachträge im geänderten Bereich vor Hauptvertrag; anschließend dieselbe Anlagenfolge und ergänzende Geltung des AN-Angebots bei Widerspruchsfreiheit; AGB/ÖNORM nur ausdrücklich.')
both('/sections/1/paragraphs/3','Die Honorarpositionen und das Gesamthonorar sind in Anlage 4 festgelegt. Leistungsumfang, Festpreis- und Zahlungsregeln, Nutzungsrechte und Sicherheiten richten sich nach diesem Vertrag und seinen Anlagen; die Rangfolge nach Abs. 3 gilt. Die Vertragsannahme erfasst das vollständige Vertragsdokument einschließlich sämtlicher Anlagen. Eine Unterzeichnung allein des Angebots in Anlage 5 ersetzt die Unterzeichnung dieses Vertrages nicht.','Elimină formularea de înlocuire a restricțiilor și «wesentliche Abweichungen»; păstrează aceleași norme de prioritate și acceptarea integrală.')
both('/sections/1/paragraphs/4','Der Leistungs- und Bedingungsumfang richtet sich nach diesem Vertrag und seinen Anlagen. Vor Unterzeichnung bestätigt der AN ausdrücklich Preisgültigkeit, Ressourcen und die relative Terminplanung. Eine Verlängerung der Angebotsgültigkeit bedarf der ausdrücklichen Bestätigung des AN. Maßgeblich ist die in Anlage 2 bestätigte tatsächliche Bauteil-/Öffnungsliste einschließlich der dazu üblich erforderlichen Koordination; diese Leistung wird nicht durch pauschale Mengen-, RFI- oder Besprechungsgrenzen beschränkt. Die physischen Ortstermine richten sich nach § 7. Eine echte spätere Umfangsänderung folgt § 11.','Elimină pluralul «Originalangebote», «neuen gemeinsamen», istoricul plafoanelor și comparația. Păstrează validitatea explicită a ofertei și lipsa limitelor ascunse, cu numărarea 12+6 după §7.','Die historischen Zahlen 15/20/6/3 waren in R06 keine vereinbarten Obergrenzen, sondern ausdrücklich verworfene historische Beschränkungen. Keine operative Leistungsmengenreduktion; bestätigte Liste/übliche Koordination bleiben maßgeblich.')
bothchange('/sections/2/paragraphs/6',[('Der vollständige gemeinsame Umfang','Der vollständige beauftragte Umfang')],'«gemeinsame» poate sugera comparația între contracte; beauftragte se referă la propriul contract.')
bothchange('/sections/3/paragraphs/0',[('kaufmännische Angebotswertung und allgemeine Vergabeverhandlungen sind ausgeschlossen.','kaufmännische Angebotswertung und allgemeine kaufmännische Vergabeabstimmungen sind ausgeschlossen.')],'Elimină rădăcina verhand din clauza de delimitare conform instrucțiunii; nu extinde și nu reduce excluderea serviciilor comerciale.')
bothchange('/sections/6/paragraphs/1',[('Anlage 3 enthält denselben phasenbezogenen Plan','Anlage 3 enthält den phasenbezogenen Plan'),('Wirtschaftliche Originalpositionen','Die Honorarpositionen')],'«denselben» și Originalpositionen pot trimite la comparația dintre propuneri; nu se schimbă numărarea unei singure prezențe.')
bothchange('/sections/6/paragraphs/3',[('Inhalt und Zählung sind für beide Anbieter gleich; nur der Preis richtet sich nach Anlage 4.','Inhalt und Zählung richten sich nach diesem Paragraphen; der Preis ist in Anlage 4 festgelegt.')],'Elimină referirea explicită la alți ofertanți; toate celelalte reguli de opțiuni rămân identice.')
bothchange('/sections/8/paragraphs/5',[('Abweichende Fristen bedürfen einer ausdrücklichen Vereinbarung und dürfen nicht als nur für einen Anbieter verbleibende unbestimmte Ziele behandelt werden.','Abweichende Fristen bedürfen einer ausdrücklichen Vereinbarung und sind mit konkretem Lieferumfang und Datum festzuhalten.')],'Elimină comparația cu un alt Anbieter, păstrând caracterul determinat și confirmarea expresă a termenelor.')
bothchange('/sections/8/paragraphs/6',[('ursprünglicher anwendbarer Tarif','vertraglich anwendbarer Tarif')],'Referință tarifară neutră; păstrează prețurile din An4 și toate drepturile legale de împiedicare.')
for pr in docs:change(pr,'/sections/10/paragraphs/0',[('wirtschaftlichen Originalpositionen','Honorarpositionen'),('sieben gemeinsame abrechenbare Ergebnistrigger','sieben vertragliche abrechenbare Ergebnistrigger')],'Elimină comparația prețurilor și graficelor; păstrează întregul onorariu și cele șapte repere.')
bothchange('/sections/11/paragraphs/0',[('die Originalpositionen und der Gesamtnettobetrag','die Honorarpositionen nach Anlage 4 und der Gesamtnettobetrag')],'Elimină eticheta istorică, păstrând interdicția depășirii sumelor și rezerva §1168 deja prezentă.')
bothchange('/sections/12/paragraphs/5',[(' Diese gleiche Vertragsstrafe ist eine neue AG-Verhandlungsbedingung für beide AN und keine aus dem historischen Angebot abgeleitete Zusage.','')],'Elimină doar ultima explicație comparativă.','0,1 % je schuldhaftem Werktag vom betroffenen Netto-Meilenstein, maximal 5 % Paket, keine Doppelkompensation und §1336-Mäßigung unverändert.')
bothchange('/sections/13/paragraphs/1',[('Die Firma, Berufsbezeichnung oder ein historischer Titel','Die Firma, Berufsbezeichnung oder ein Titel allein')],'Elimină conotația istorică din prezentare; calificările active pe rol, inclusiv regula rB, rămân.')
both('/sections/13/paragraphs/3','Die aktuell tatsächlich vorhandene und ausdrücklich bestätigte berufliche Deckung ist in Anlage 6 festzuhalten. Eine darüber hinausgehende vertragliche Mindestdeckung oder Jahresmaximierung wird nicht gefordert; zwingende gesetzliche Versicherungspflichten der jeweiligen Tätigkeit bleiben uneingeschränkt bestehen. Der Nachweis muss aktuell sein und die übernommenen Funktionen erfassen. Die dokumentierte Versicherungssumme begrenzt die Haftung des AN nicht und ersetzt keinen fehlenden Deckungsnachweis.','Elimină comparația cu cerința numerică anterioară/istoric; păstrează lipsa unei cerințe contractuale suplimentare, polița actuală, rolurile și obligațiile imperative.')
bothchange('/annexes/1/tables/0/rows/8/1',[('Gemeinsam bestätigen; keine stillschweigenden historischen Mengen-/RFI-/Besprechungslimits','Beiderseits bestätigen; maßgebliche Bauteil-/Öffnungsliste und übliche fachliche Koordination nach § 2')],'Elimină explicația comparativă istorică; lista efectivă și coordonarea rămân.')
both('/annexes/2/paragraphs/0','Die tatsächlichen Daten werden vor Unterzeichnung beziehungsweise bei tatsächlichem Beginn ausdrücklich bestätigt. Die relativen Lieferfristen richten sich nach § 9 und diesem Terminplan. Vor Vertragsabschluss beginnt aus dieser Vorlage allein kein Fristenlauf. T0 und der tatsächliche bauliche B0 sind getrennte Bezugspunkte.','Elimină «neue gemeinsame Verhandlungsbedingungen», fără a modifica fristen/T0/B0.')
bothchange('/annexes/2/paragraphs/1',[('Die untenstehende phasenbezogene Verteilung gilt für beide AN.','Die untenstehende phasenbezogene Verteilung ist für die tatsächlichen Bauphasen vorgesehen.')],'Elimină referirea la ambii AN; T0 separat, 12 fizice și numărarea rămân.')
both('/annexes/3/paragraphs/0','Die Honorarpositionen und ihre Beträge sind in der folgenden Tabelle festgelegt. Die Zahlungsstaffel verteilt das gesamte Paket auf die sieben vollständigen Ergebnisse E1-E7 zu 10/20/25/15/10/10/10 Prozent. Kein Betrag darf derselben Leistung zweimal zugeordnet werden. Die Summen gelten vor Haftrücklass; gesetzliche Umsatzsteuer wird gesondert ausgewiesen.','Elimină original/neu/dieselben/AG-Verhandlung; păstrează toate cele șapte procente și sumele.')
both('/annexes/3/paragraphs/4','Im Grundhonorar sind zwölf physische B0-Ortstermine und die zusätzlich enthaltene anfängliche T0-Begehung nach §§ 7 und 8 enthalten. Bis zu sechs weitere physische Ortstermine können einzeln zu dem nachstehend festgelegten Tarif beauftragt werden. Umfang und Bauphasenrahmen richten sich nach diesem Vertrag.','Înlocuiește istoricul particular B8→12 și istoricul P12/450 prin enunțul contractual neutru; tariful specific rămâne integral în alin6/tabele.','BERGER EUR2.000/12 kumulativ und PECH EUR450 bleiben in Anlage4(6) unverändert; keine automatische Bestellung.')
bothchange('/annexes/3/paragraphs/7',[('eine neue Kalkulations- und Abrechnungsgliederung der unveränderten Originalbeträge','die Kalkulations- und Abrechnungsgliederung der Honorarpositionen'),('sie begrenzt keine gemeinsame Leistung','sie begrenzt keine beauftragte Leistung'),('dem Originalbetrag','dem jeweiligen Positionsbetrag')],'Elimină istoric/comparație; alocarea numerică, fiecare euro o dată și E7/BWB anticipat nu se schimbă.')
change('PECH','/annexes/3/paragraphs/8',[('der ursprünglichen Position 04','der Position 04')],'Elimină «ursprünglichen», păstrând expres EUR800/EUR6.130 și PI406,67/813,33/1.220.')
