bothchange('/annexes/5/tables/1/rows/3/1',[('zwölf gemeinsame physische B0-Termine','zwölf physische B0-Termine'),('mit gleichem Inhalt und anbieterabhängigem Preis','nach § 7 zu den Preisen der Anlage 4')],'Elimină Vergleich/Anbieter; păstrează T0, primulUnder, 12+6 și nedublarea.')
bothchange('/annexes/5/tables/1/rows/5/1',[('Jeweiliger Paketpreis und Originalpositionen','Paketpreis und Honorarpositionen')],'Elimină diferențierea furnizorilor și istoric; prețul și drepturile §1168 sunt păstrate.')
bothchange('/annexes/5/tables/1/rows/6/1',[('Gleiche sieben Ergebnistrigger','Sieben vertragliche Ergebnisse')],'Elimină comparația în rândul plăților; procentele și condițiile rămân.')
